// Regression test for: Signup accepts invalid email address without '@'
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #10.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("signup rejects an email address without '@'", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  await page.goto("/signup");
  await page.getByLabel("Email", { exact: true }).fill("notanemail");
  await page.getByLabel("Password", { exact: true }).fill("password123");
  await page.getByRole("button", { name: "Create account" }).click();

  await expect(
    page.getByText("Please enter a valid email address.", { exact: true })
  ).toBeVisible();
  await expect(page.getByText(/Welcome, notanemail/)).toHaveCount(0);

  expect(pageErrors).toEqual([]);
});
